package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSwDraft7 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_jar_su" to DuaText("Kimbilio Kutoka kwa Jirani Mbaya", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na jirani mbaya katika sehemu ya makazi ya kudumu, kwani jirani katika safari husonga mbele.", "Kwa ulinzi kutoka kwa jirani mbaya.", "Mtume ﷺ aliamuru kutafuta hifadhi kutokana na hili."),
        "dua_ishfi_abdak" to DuaText("Kwa Ajili ya Kupona Mgonjwa", "Ewe Mwenyezi Mungu, mponye mja wako ili akumbane na adui kwa ajili Yako au atembee kwenye maombi kwa ajili Yako.", "Kwa mgonjwa wakati wa kumtembelea.", "Mtume ﷺ alifundisha akisema hivi kwa ajili ya wagonjwa."),
        "dua_la_mania" to DuaText("Hakuna Anayeweza Kuzuia Unachotoa", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, peke yake, asiye na mshirika. Ufalme ni wake, na sifa njema ni zake, na Yeye ni Muweza wa kila kitu. Ewe Mwenyezi Mungu, hakuna awezaye kunyima Utoacho na hakuna wa kutoa unachokinyima, na mali ya matajiri haina faida kwako.", "Baada ya salam ya swala ya faradhi.", "Mtume ﷺ alisema haya baada ya kila swala ya faradhi."),
        "dua_slaughtering" to DuaText("Wakati wa Kuchinja Mnyama", "Kwa jina la Mwenyezi Mungu, na Mwenyezi Mungu ndiye Mkubwa.", "Wakati wa kutoa dhabihu au kuchinja mnyama.", "Mtume ﷺ alisema Bismillah na takbir wakati wa kutoa sadaka."),
        "dua_undressing" to DuaText("Wakati wa Kuvua Nguo", "Kwa jina la Mwenyezi Mungu.", "Wakati wa kuvua nguo (kwa ghusl au kubadilisha).", "Inakuwa skrini kati ya macho ya jini na sehemu za siri za mtu."),
        "dua_ilbas_jadidan" to DuaText("Kuona Mtu Katika Nguo Mpya", "Vaa mpya, ishi kwa sifa na ufe shahidi.", "Kwa kumuona ndugu Mwislamu akiwa amevaa nguo mpya.", "Mtume ﷺ alifanya dua hii kwa kumuona Umar (RA) katika nguo mpya."),
        "dua_hajj_la_riya" to DuaText("Hajj Isiyoonyeshwa", "Ewe Mwenyezi Mungu, (ifanye) kuwa ni Hijja isiyo na majivuno wala kutafuta umaarufu.", "Kwa ikhlasi wakati wa kufanya nia ya Hijja.", "Mtume ﷺ alifanya dua hii wakati wa Hijja."),
        "dua_q_muslimayni_laka" to DuaText("Dua ya Ibrahim & Ismail (AS) - Tufanye Wanyenyekevu", "Mola wetu Mlezi! Utujaalie tuwe watu wenye kujinyenyekeza Kwako na katika dhuria zetu tuwe umma unaonyenyekea kwako. Tuonyeshe ibada zetu na ukubali toba yetu. Hakika Wewe ni Mwenye kupokea toba, Mwenye kurehemu.", "Dua ya kujisalimisha kwa ajili ya nafsi yake na vizazi vyake.", "Dua iliyofanywa wakati wa kujenga Ka'bah."),
        "dua_q_iftah_baynana" to DuaText("Dua ya Shu'aib (AS) - Hakimu Baina Yetu", "Mola wetu Mlezi, tuhukumu baina yetu na watu wetu kwa haki, na Wewe ndiye mbora wa mahakimu.", "Kwa hukumu kati ya ukweli na uwongo.", "Dua ya Shuayb (AS) watu wake walipomkataa."),
        "dua_q_la_akuna_zahiran" to DuaText("Dua ya Musa (AS) - Kamwe Msaidizi wa Wahalifu", "Mola wangu Mlezi, kwa neema uliyo nineemesha, sitakuwa msaidizi wa wakosefu.", "Kushukuru neema za Mwenyezi Mungu na ahadi ya kutowanusuru madhalimu.", "Ahadi ya Musa (AS) baada ya toba yake."),
        "dua_q_nuh_unsurni" to DuaText("Dua ya Nuh (AS) - Nisaidie, Wananikana", "Mola wangu Mlezi, nisaidie, kwani wamenikana.", "Watu wakikukana na kuukataa ukweli.", "Dua ya Nuh (AS), ambayo ilijibiwa."),
        "dua_q_ihkum_bil_haqq" to DuaText("Mola Wangu, Hukumu kwa Haki", "Mola wangu Mlezi, hukumu kwa haki. Na Mola wetu ni Mwingi wa kurehemu, ambaye huombwa msaada wake juu ya hayo mnayo yaeleza.", "Mbele ya uwongo na shutuma za uwongo.", "Dua aliyofunzwa Mtume ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Kimbilio Kutokana na Kusagwa Madeni na Maadui", "Ewe Mwenyezi Mungu, najikinga Kwako nisipitishwe na deni, na kushindwa na adui na kutokamana na shauku ya maadui.", "Ulinzi kutoka kwa mzigo wa deni na kutawaliwa na maadui.", "Mtume ﷺ alikuwa akijikinga na mambo haya."),
        "dua_faqr_qillah_dhillah" to DuaText("Kimbilio Kutoka kwa Umaskini na Unyonge", "Ewe Mwenyezi Mungu, mimi najikinga Kwako kutokana na umasikini, uhaba na unyonge, na kuwadhulumu wengine au kudhulumiwa.", "Kuwa salama kutoka kwa shida, hamu na fedheha.", "Kimbilio lililofundishwa na Mtume ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Samehe, Rehema, Mwongozo, Uponya, Toa", "Ewe Mwenyezi Mungu, nisamehe, nirehemu, niongoze, nipe kheri na uniruzuku.", "Mtume ﷺ alifundisha dua hii, pamoja na sala, kwa Waislamu wapya.", "Mtume ﷺ amesema: maneno haya yanakukusanyia dunia na Akhera."),
        "dua_ruku_laka_raka_tu" to DuaText("Katika Rukuu - Kwako Nimeinama", "Ewe Mwenyezi Mungu, nimeinama kwako, nimekuamini na nimesilimu kwako. Kusikia kwangu, kuona kwangu, akili yangu, mifupa yangu na mishipa yangu imenyenyekezwa mbele zako.", "Katika rukuu (hasa katika sala za hiari).", "Mtume ﷺ amekariri haya kwa rukuu."),
        "dua_sujood_laka_sajadtu" to DuaText("Katika Sujuud - Nimekusujudia", "Ewe Mwenyezi Mungu nimesujudu kwako, nimekuamini na nimesilimu kwako. Uso wangu umemsujudia aliye umba, na akautengeneza na akatoa kusikia kwake na kuona kwake. Ametukuka Mwenyezi Mungu Mbora wa waumbaji.", "Katika sujuud (hasa katika sala za kujitolea).", "Mtume ﷺ alikariri haya kwa sujuud."),
        "dua_ruku_sujood_subhanaka" to DuaText("Umetakasika, Mola Wetu - Nisamehe", "Umetakasika, Ewe Mwenyezi Mungu, Mola wetu, na sifa njema ni Zako. Ewe Mwenyezi Mungu nisamehe.", "Katika rukuu na sujuud.", "Aisha (RA): Mtume ﷺ mara nyingi alisema hivi kwa rukuu na sujuud."),
        "dua_q_musa_li_akhi" to DuaText("Dua ya Musa (AS) - Nisamehe Mimi na Ndugu Yangu", "Mola wangu Mlezi, nisamehe mimi na ndugu yangu na utuingize katika rehema yako, kwani Wewe ni Mwingi wa kurehemu kuliko wanaorehemu.", "Msamaha kwa nafsi yako na ndugu au wapendwa.", "Dua ya Musa (AS) kwa Harun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Namukabidhi Mwenyezi Mungu Mambo Yangu", "Na mimi namkabidhi Mwenyezi Mungu mambo yangu. Hakika Mwenyezi Mungu ni Mwenye kuwaona waja wake.", "Watu wanapokupinga na jambo hilo lazima liachiwe kwa Mwenyezi Mungu.", "Maneno ya Muumini kutoka kwa watu wa Firauni; Kisha Mwenyezi Mungu akamlinda na vitimbi vyao viovu."),
        "dua_q_hawariyyun" to DuaText("Dua ya Wanafunzi — Tuandikishe Pamoja na Mashahidi", "Mola wetu Mlezi, tumeyaamini uliyoyateremsha na tumemfuata Mtume, basi tuandikishe miongoni mwa mashahidi.", "Kwa ajili ya uthabiti katika imani na kumfuata Mtume.", "Dua ya wanafunzi wa Isa (AS)."),
        "dua_q_la_tukhzini" to DuaText("Dua ya Ibrahim (AS) - Usinifedheheshe", "Wala usinihizi Siku watapo fufuliwa.", "Kusalimika na fedheha Siku ya Kiyama.", "Dua ya Ibrahim (AS) ya Akhera."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar - Kwa ajili yako Nimefunga", "Ee Mwenyezi Mungu, kwa ajili Yako nimefunga na kwa riziki Yako nafungua saumu yangu.", "Wakati wa kufuturu (iftar dua inayojulikana sana).", "Mtume ﷺ alisema hivi kwenye iftar. Ni riwaya ya mursal iliyotiwa nguvu na riwaya zingine; kuisoma katika iftar ni desturi ya Mahanafi na walio wengi."),
        "dua_iftar_ibn_umar" to DuaText("Iftar - Kwa Rehema Zako Kubwa, Nisamehe", "Ewe Mwenyezi Mungu, nakuomba unisamehe kwa rehema yako ambayo imekizunguka kila kitu.", "Katika iftar - Abdullah ibn Amr (RA) alifanya dua hii; dua ya mfungaji katika iftari haikatazwi.", "Hadithi: dua ya mfungaji wakati wa iftari haikatazwi."),
        "dua_inni_saim" to DuaText("Wakati Wa Kuchokozwa Wakati Wa Kufunga", "Ninafunga, ninafunga.", "Mtu anapokutukana au kugombana nawe akiwa amefunga.", "Mtume ﷺ amesema: Saumu ni ngao, kwa hivyo mfungaji hatakiwi kusema machafu au kufanya ujinga - ikiwa mtu anagombana, sema hivi mara mbili."),
        "dua_eid_takbeer" to DuaText("Takbira katika Njia ya Idi", "Mwenyezi Mungu ndiye Mkubwa, Mwenyezi Mungu ndiye Mkubwa, hapana mungu ila Mwenyezi Mungu, na Mwenyezi Mungu ndiye Mkubwa, Mwenyezi Mungu ndiye Mkubwa, na sifa njema zote ni za Mwenyezi Mungu.", "Kuanzia usiku wa kuandama mwezi hadi Sala ya Eid al-Fitr, haswa katika njia ya kuelekea uwanja wa Idi.", "Amri ya Qur'an: 'Ili mkamilishe hisabu na utangaze ukuu wa Mwenyezi Mungu' (al-Baqarah 2:185). Ibn Mas'ud (RA) alisema takbira hii."),
        "dua_ahsin_aqibatana" to DuaText("Ufanye Mwisho Wetu Mwema Katika Mambo Yote", "Ewe Mwenyezi Mungu, Ujaalie mwisho wetu uwe mzuri katika kila jambo, na Utulinde na fedheha duniani na adhabu Akhera.", "Kwa matokeo mazuri katika kila jambo.", "Anayefanya dua hii na akafa kabla ya kujaribiwa atakufa (amesalimika na hukumu)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Naomba Fadhila na Rehema Zako", "Ewe Mwenyezi Mungu, nakuomba fadhila Zako na rehema Zako, kwani hakuna mwenye nazo ila Wewe.", "Wakati wa kuomba riziki na rehema.", "Wageni walikuja kwa Mtume ﷺ wakati hapakuwa na chakula; alifanya dua hii, na kisha zawadi ikafika."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Maneno Yanayofundishwa kwa Bedui", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, peke yake, asiye na mshirika. Mwenyezi Mungu ndiye Mkubwa kabisa; Sifa njema zote ni za Mwenyezi Mungu. ametakasika Mwenyezi Mungu, Mola Mlezi wa walimwengu wote. na hakuna nguvu wala uwezo ila kwa Mwenyezi Mungu, Mwenye nguvu, Mwenye hikima.", "Kifungu cha maneno cha kina cha dhikr na dua - kilichofundishwa kwa Bedui.", "Baada ya hapo alifunzwa kusema 'Allahummaghfir li warhamni wahdini warzuqni'."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Samehe Nilichotuma Kabla na Baada", "Ewe Mwenyezi Mungu, nighufirie madhambi niliyoyafanya kabla na baada yake, niliyoyafanya kwa siri na niliyoyafanya waziwazi, na kupita kiasi kwangu, na unayoyajua zaidi kuliko mimi. Wewe ndiye mwenye kuleta mbele na ndiye anayerudisha nyuma; hakuna mungu ila Wewe.", "Baada ya tashahhud na salawat, kabla ya salamu.", "Mtume ﷺ aliyasoma haya mwishoni mwa swala, baina ya tashahhud na salam."),
        "dua_jiddi_wa_hazli" to DuaText("Nisamehe Uzito Wangu na Utani Wangu", "Ewe Mwenyezi Mungu, nisamehe madhambi niliyoyafanya makubwa na kwa mzaha, kwa kukosea na kwa makusudi - na yote hayo yamo ndani yangu.", "Msamaha kwa kila aina ya dhambi, inayojulikana na isiyojulikana.", "Istighfar pana ya Mtume ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Baada ya Rukuu - Sifa Kujaza Mbingu", "Mola wetu Mlezi, sifa njema zote ni Zako, unaijaza mbingu, na unaijaza ardhi, na ukijaza utakalo baada ya hayo.", "Baada ya kuinuka kutoka kwenye rukuu, pamoja na 'Rabbana lakal-hamd'.", "Mtume ﷺ alisema haya alipoinuka kutoka rukuu."),
        "dua_istiftah_kabira" to DuaText("Mwenyezi Mungu ni Mkuu, Msifiwa mwingi", "Mwenyezi Mungu ndiye Mkubwa kabisa; Sifa njema zote ni za Mwenyezi Mungu. na ametakasika Mwenyezi Mungu asubuhi na jioni.", "Wakati wa kuanza maombi (aina moja ya sifa ya ufunguzi).", "Mtume ﷺ amesema: milango ya mbinguni ilifunguliwa kwa ajili yake."),
        "dua_q_ashku_bathhi" to DuaText("Dua ya Yaqub (AS) - Ninalalamika kwa Mwenyezi Mungu tu", "Ninalalamikia uchungu wangu na huzuni yangu kwa Mwenyezi Mungu tu.", "Katika huzuni kubwa na kujitenga.", "Ya'qub (AS) alisema haya katika kujitenga kwake na Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Mwenyezi Mungu ndiye Mlinzi bora", "Mwenyezi Mungu ndiye Mlinzi bora, na ni Mwingi wa kurehemu kuliko wanaorehemu.", "Wakati wa kutuma watoto au wapendwa kwenye safari.", "Ya'qub (AS) alisema hayo huku akimkabidhi mtoto wake kwa Mwenyezi Mungu."),
        "dua_q_aqraba_rashada" to DuaText("Mola Wangu Aniongoze Karibu Na Haki", "Labda Mola wangu Mlezi ataniongoza kwenye yaliyo karibu zaidi kuliko haya kwenye uwongofu.", "Wakati wa kutafuta njia bora katika jambo fulani.", "Mtume ﷺ aliambiwa aseme hivi baada ya kusahau."),
        "dua_q_sawa_as_sabil" to DuaText("Dua ya Musa (AS) - Niongoze kwenye Njia Iliyo Nyooka", "Labda Mola wangu Mlezi ataniongoza kwenye njia iliyonyooka.", "Wakati wa kuanza safari mpya au barabara isiyojulikana.", "Musa (AS) alisema hivyo huku akielekea Madyan."),
        "dua_q_not_among_wrongdoers" to DuaText("Usiniweke Miongoni Mwa Madhalimu", "Mola wangu Mlezi, usiniweke miongoni mwa watu madhalimu.", "Dua ya kumuomba Mwenyezi Mungu amtenge mbali na madhalimu.", "Dua ya kumuomba Mwenyezi Mungu amtenge mbali na madhalimu."),
        "dua_q_do_not_make_us_trial" to DuaText("Usitufanye Kuwa Jaribio", "Mola wetu Mlezi, usitufanye kuwa mtihani kwa makafiri, na utusamehe Mola wetu Mlezi. Hakika Wewe ndiye Mwenye nguvu, Mwenye hikima.", "Dua ya Ibrahim (AS) na maswahaba zake.", "Dua ya Ibrahim (AS) na maswahaba zake."),
        "dua_morning_witness" to DuaText("Asubuhi Shuhudia Tawhid", "Ewe Mwenyezi Mungu, nimeingia asubuhi nikiwalingania Wewe washika Arshi Yako, Malaika Wako na viumbe Wako wote, washuhudie kwamba Wewe ni Mwenyezi Mungu, hapana mungu ila Wewe, peke yako, bila mshirika, na kwamba Muhammad ﷺ ni mja wako na Mtume wako.", "Riwaya inataja kusema hivyo mara nne asubuhi.", "Riwaya inataja kusema hivyo mara nne asubuhi."),
    )
}
